     1→/* ============================================================================
     2→   Nano Memory Pool - FreeLang Nano-Kernel
     3→
     4→   목적: 정적 페이지 풀로 1MB 상한 메모리 관리 (256 × 4KB)
     5→   크기: ~350줄
     6→   성능: 페이지 할당/해제 < 1µs
     7→
     8→   설계: PhysicalPage (bootloader.fl) 패턴 재사용
     9→   - 256개 4KB 페이지 = 1MB 총합
    10→   - 비트맵 기반 할당 (8×32비트 = 256비트)
    11→   - O(1) 할당/해제 성능
    12→============================================================================ */
    13→
    14→// ============================================================================
    15→// 1. 상수 정의
    16→// ============================================================================
    17→
    18→pub const PAGE_SIZE: u32 = 4096;           // 4KB per page
    19→pub const PAGE_COUNT: u32 = 256;           // 256 pages = 1MB
    20→pub const MEMORY_POOL_SIZE: u32 = PAGE_SIZE * PAGE_COUNT;  // 1,048,576 bytes
    21→pub const BITMAP_SIZE: u32 = 8;            // 256비트 = 8개 u32
    22→
    23→// ============================================================================
    24→// 2. 페이지 풀 구조체
    25→// ============================================================================
    26→
    27→pub struct NanoPagePool {
    28→    // 256 × 4KB 정적 메모리 풀
    29→    pub pages: [u64; 256],                 // 256 물리 페이지 주소 (32KB 메타)
    30→
    31→    // 비트맵: 페이지 할당 상태 추적
    32→    pub bitmap: [u32; 8],                  // 256 페이지 = 256비트 = 8×u32
    33→
    34→    // 통계
    35→    pub total_pages: u32,
    36→    pub used_pages: u32,
    37→    pub free_pages: u32,
    38→    pub allocation_count: u32,
    39→    pub deallocation_count: u32,
    40→    pub max_used_pages: u32,
    41→}
    42→
    43→impl NanoPagePool {
    44→    pub fn new() -> Self {
    45→        let mut pool = NanoPagePool {
    46→            pages: [0u64; 256],
    47→            bitmap: [0u32; 8],
    48→            total_pages: PAGE_COUNT,
    49→            used_pages: 0,
    50→            free_pages: PAGE_COUNT,
    51→            allocation_count: 0,
    52→            deallocation_count: 0,
    53→            max_used_pages: 0,
    54→        };
    55→
    56→        // 물리 주소 초기화: 0x80000000 + page_idx × 4096
    57→        for i in 0..256 {
    58→            pool.pages[i] = (0x80000000u64 + (i as u64 * PAGE_SIZE as u64));
    59→        }
    60→
    61→        pool
    62→    }
    63→
    64→    /// 사용률 (%)
    65→    pub fn usage_percent(&self) -> u32 {
    66→        if self.total_pages == 0 {
    67→            return 0;
    68→        }
    69→        (self.used_pages * 100) / self.total_pages
    70→    }
    71→
    72→    /// 메모리 사용량 (KB)
    73→    pub fn used_kb(&self) -> u32 {
    74→        (self.used_pages * PAGE_SIZE) / 1024
    75→    }
    76→
    77→    /// 메모리 여유량 (KB)
    78→    pub fn free_kb(&self) -> u32 {
    79→        (self.free_pages * PAGE_SIZE) / 1024
    80→    }
    81→
    82→    /// 통계 조회
    83→    pub fn stats(&self) -> (u32, u32, u32, u32, u32, u32) {
    84→        (
    85→            self.total_pages,
    86→            self.used_pages,
    87→            self.free_pages,
    88→            self.allocation_count,
    89→            self.deallocation_count,
    90→            self.max_used_pages,
    91→        )
    92→    }
    93→}
    94→
    95→// ============================================================================
    96→// 3. 페이지 할당자
    97→// ============================================================================
    98→
    99→pub struct PageAllocator {
   100→    pub pool: NanoPagePool,
   101→    pub last_allocated_idx: u32,
   102→    pub allocation_strategy: u8,  // 0=first-fit, 1=next-fit
   103→}
   104→
   105→impl PageAllocator {
   106→    pub fn new() -> Self {
   107→        PageAllocator {
   108→            pool: NanoPagePool::new(),
   109→            last_allocated_idx: 0,
   110→            allocation_strategy: 1,  // next-fit (빠른 할당)
   111→        }
   112→    }
   113→
   114→    /// 단일 페이지 할당
   115→    /// 성공 시 물리 주소 반환, 실패 시 None
   116→    pub fn alloc_page(&mut self) -> Option<u64> {
   117→        if self.pool.free_pages == 0 {
   118→            return None;  // 메모리 부족
   119→        }
   120→
   121→        // Next-fit 전략
   122→        let start_idx = self.last_allocated_idx;
   123→        let mut idx = start_idx;
   124→
   125→        loop {
   126→            let bitmap_idx = (idx / 32) as usize;
   127→            let bit_idx = idx % 32;
   128→
   129→            if bitmap_idx >= BITMAP_SIZE as usize {
   130→                // 끝에 도달, 처음부터 다시
   131→                if idx == start_idx {
   132→                    return None;  // 전체 순회했으나 못 찾음
   133→                }
   134→                idx = 0;
   135→                continue;
   136→            }
   137→
   138→            // 비트맵 확인: 0 = free, 1 = allocated
   139→            if (self.pool.bitmap[bitmap_idx] & (1 << bit_idx)) == 0 {
   140→                // 이 페이지는 비어있음
   141→                self.pool.bitmap[bitmap_idx] |= 1 << bit_idx;
   142→
   143→                self.pool.used_pages += 1;
   144→                self.pool.free_pages -= 1;
   145→                self.pool.allocation_count += 1;
   146→
   147→                if self.pool.used_pages > self.pool.max_used_pages {
   148→                    self.pool.max_used_pages = self.pool.used_pages;
   149→                }
   150→
   151→                let addr = self.pool.pages[idx as usize];
   152→                self.last_allocated_idx = (idx + 1) % PAGE_COUNT;
   153→
   154→                return Some(addr);
   155→            }
   156→
   157→            idx = (idx + 1) % PAGE_COUNT;
   158→
   159→            if idx == start_idx {
   160→                // 한 바퀴 다 돌았는데 못 찾음
   161→                return None;
   162→            }
   163→        }
   164→    }
   165→
   166→    /// 여러 페이지 할당 (연속 메모리 미보장)
   167→    pub fn alloc_pages(&mut self, count: u32) -> Vec<u64> {
   168→        let mut addrs = Vec::new();
   169→
   170→        for _ in 0..count {
   171→            match self.alloc_page() {
   172→                Some(addr) => addrs.push(addr),
   173→                None => break,  // 부족하면 부분 할당
   174→            }
   175→        }
   176→
   177→        addrs
   178→    }
   179→
   180→    /// 페이지 해제
   181→    pub fn free_page(&mut self, addr: u64) -> bool {
   182→        // 주소로부터 페이지 인덱스 계산
   183→        let base = 0x80000000u64;
   184→
   185→        if addr < base || addr >= base + (PAGE_COUNT as u64 * PAGE_SIZE as u64) {
   186→            return false;  // 범위 외 주소
   187→        }
   188→
   189→        let offset = (addr - base) / PAGE_SIZE as u64;
   190→        if offset >= PAGE_COUNT as u64 {
   191→            return false;
   192→        }
   193→
   194→        let idx = offset as u32;
   195→        let bitmap_idx = (idx / 32) as usize;
   196→        let bit_idx = idx % 32;
   197→
   198→        if bitmap_idx >= BITMAP_SIZE as usize {
   199→            return false;
   200→        }
   201→
   202→        // 비트 확인: 할당된 상태여야 함
   203→        if (self.pool.bitmap[bitmap_idx] & (1 << bit_idx)) == 0 {
   204→            return false;  // 이미 해제됨 (double-free 시도)
   205→        }
   206→
   207→        // 할당 해제
   208→        self.pool.bitmap[bitmap_idx] &= !(1 << bit_idx);
   209→
   210→        self.pool.used_pages -= 1;
   211→        self.pool.free_pages += 1;
   212→        self.pool.deallocation_count += 1;
   213→
   214→        true
   215→    }
   216→
   217→    /// 모든 페이지 해제
   218→    pub fn free_all(&mut self) {
   219→        self.pool.bitmap = [0u32; 8];
   220→        self.pool.used_pages = 0;
   221→        self.pool.free_pages = PAGE_COUNT;
   222→        self.pool.last_allocated_idx = 0;
   223→    }
   224→
   225→    /// 할당된 페이지 개수
   226→    pub fn allocated_count(&self) -> u32 {
   227→        self.pool.used_pages
   228→    }
   229→
   230→    /// 여유 페이지 개수
   231→    pub fn free_count(&self) -> u32 {
   232→        self.pool.free_pages
   233→    }
   234→}
   235→
   236→// ============================================================================
   237→// 4. 메모리 영역 할당자 (다중 크기 지원)
   238→// ============================================================================
   239→
   240→pub struct MemoryRegion {
   241→    pub start_addr: u64,
   242→    pub size: u32,
   243→    pub allocated: bool,
   244→}
   245→
   246→pub struct RegionAllocator {
   247→    pub regions: Vec<MemoryRegion>,
   248→    pub page_alloc: PageAllocator,
   249→}
   250→
   251→impl RegionAllocator {
   252→    pub fn new() -> Self {
   253→        RegionAllocator {
   254→            regions: Vec::new(),
   255→            page_alloc: PageAllocator::new(),
   256→        }
   257→    }
   258→
   259→    /// 임의 크기 메모리 할당
   260→    pub fn alloc(&mut self, size: u32) -> Option<u64> {
   261→        if size == 0 || size > MEMORY_POOL_SIZE {
   262→            return None;
   263→        }
   264→
   265→        // 필요한 페이지 수 계산
   266→        let pages_needed = (size + PAGE_SIZE - 1) / PAGE_SIZE;
   267→
   268→        // 페이지 할당
   269→        let addrs = self.page_alloc.alloc_pages(pages_needed);
   270→        if addrs.is_empty() {
   271→            return None;
   272→        }
   273→
   274→        let start_addr = addrs[0];
   275→
   276→        // 할당 영역 기록
   277→        self.regions.push(MemoryRegion {
   278→            start_addr,
   279→            size,
   280→            allocated: true,
   281→        });
   282→
   283→        Some(start_addr)
   284→    }
   285→
   286→    /// 메모리 해제
   287→    pub fn free(&mut self, addr: u64) -> bool {
   288→        // 영역 찾기
   289→        let mut region_idx = None;
   290→        for i in 0..self.regions.len() {
   291→            if self.regions[i].start_addr == addr && self.regions[i].allocated {
   292→                region_idx = Some(i);
   293→                break;
   294→            }
   295→        }
   296→
   297→        if let Some(idx) = region_idx {
   298→            let region = &self.regions[idx];
   299→
   300→            // 페이지 해제
   301→            let pages_to_free = (region.size + PAGE_SIZE - 1) / PAGE_SIZE;
   302→            for i in 0..pages_to_free {
   303→                let page_addr = region.start_addr + (i as u64 * PAGE_SIZE as u64);
   304→                self.page_alloc.free_page(page_addr);
   305→            }
   306→
   307→            self.regions.remove(idx);
   308→            return true;
   309→        }
   310→
   311→        false
   312→    }
   313→
   314→    /// 통계
   315→    pub fn memory_stats(&self) -> (u32, u32, u32) {
   316→        let (total, used, free, _, _, _) = self.page_alloc.pool.stats();
   317→        (total * PAGE_SIZE, used * PAGE_SIZE, free * PAGE_SIZE)
   318→    }
   319→}
   320→
   321→// ============================================================================
   322→// 5. 검증 함수
   323→// ============================================================================
   324→
   325→pub fn validate_page_addr(addr: u64) -> bool {
   326→    let base = 0x80000000u64;
   327→    let top = base + (PAGE_COUNT as u64 * PAGE_SIZE as u64);
   328→    addr >= base && addr < top
   329→}
   330→
   331→pub fn validate_page_alignment(addr: u64) -> bool {
   332→    addr % PAGE_SIZE as u64 == 0
   333→}
   334→
   335→pub fn validate_allocation_count(count: u32) -> bool {
   336→    count > 0 && count <= PAGE_COUNT
   337→}
   338→
   339→pub fn validate_memory_size(size: u32) -> bool {
   340→    size > 0 && size <= MEMORY_POOL_SIZE
   341→}
   342→
   343→pub fn validate_pool_integrity(pool: &NanoPagePool) -> bool {
   344→    // 통계 검증
   345→    if pool.used_pages + pool.free_pages != pool.total_pages {
   346→        return false;
   347→    }
   348→
   349→    // 비트맵 검증 (0-1만 포함)
   350→    for i in 0..8 {
   351→        if pool.bitmap[i] > 0xFFFFFFFF {
   352→            return false;
   353→        }
   354→    }
   355→
   356→    true
   357→}
   358→
   359→// ============================================================================
   360→// 6. 클론 구현
   361→// ============================================================================
   362→
   363→impl Clone for MemoryRegion {
   364→    fn clone(&self) -> Self {
   365→        MemoryRegion {
   366→            start_addr: self.start_addr,
   367→            size: self.size,
   368→            allocated: self.allocated,
   369→        }
   370→    }
   371→}
   372→

