     1→/* ============================================================================
     2→   Signal Channel - FL-Signal Transport Layer 1
     3→
     4→   목적: P2P 직접 통신 채널 + 핸드셰이크
     5→   특징:
     6→   - 로컬 키, 원격 키
     7→   - ECDH 세션 키 교환
     8→   - 메시지 송수신
     9→   - 처리량 > 10,000 msg/s
    10→   - 핸드셰이크 < 5ms
    11→
    12→   크기: ~400줄
    13→   성능: handshake < 5ms, throughput > 10K msg/s
    14→   규칙 3: P2P 레이턴시 < 10ms
    15→============================================================================ */
    16→
    17→// ============================================================================
    18→// 1. 채널 상태 열거형
    19→// ============================================================================
    20→
    21→pub enum ChannelState {
    22→    Idle = 0,           // 미초기화
    23→    Handshake = 1,      // 핸드셰이크 진행 중
    24→    Active = 2,         // 활성 통신
    25→    Closed = 3,         // 폐쇄됨
    26→}
    27→
    28→impl ChannelState {
    29→    pub fn to_u8(&self) -> u8 {
    30→        match self {
    31→            ChannelState::Idle => 0,
    32→            ChannelState::Handshake => 1,
    33→            ChannelState::Active => 2,
    34→            ChannelState::Closed => 3,
    35→        }
    36→    }
    37→}
    38→
    39→impl Clone for ChannelState {
    40→    fn clone(&self) -> Self {
    41→        match self {
    42→            ChannelState::Idle => ChannelState::Idle,
    43→            ChannelState::Handshake => ChannelState::Handshake,
    44→            ChannelState::Active => ChannelState::Active,
    45→            ChannelState::Closed => ChannelState::Closed,
    46→        }
    47→    }
    48→}
    49→
    50→// ============================================================================
    51→// 2. Signal Channel 구조체
    52→// ============================================================================
    53→
    54→pub struct SignalChannel {
    55→    pub channel_id: u64,                  // 채널 ID (unique)
    56→    pub local_key: [u8; 32],              // 로컬 공개 키
    57→    pub remote_key: [u8; 32],             // 원격 공개 키
    58→    pub session_key: [u8; 32],            // ECDH 세션 키
    59→    pub state: ChannelState,              // 채널 상태
    60→    pub message_count: u64,               // 송수신 메시지 카운트
    61→    pub bytes_sent: u64,                  // 전송 바이트
    62→    pub bytes_received: u64,              // 수신 바이트
    63→    pub created_timestamp: u64,           // 채널 생성 시간
    64→}
    65→
    66→impl SignalChannel {
    67→    pub fn new(channel_id: u64, local_key: &[u8; 32]) -> Self {
    68→        SignalChannel {
    69→            channel_id,
    70→            local_key: *local_key,
    71→            remote_key: [0u8; 32],
    72→            session_key: [0u8; 32],
    73→            state: ChannelState::Idle,
    74→            message_count: 0,
    75→            bytes_sent: 0,
    76→            bytes_received: 0,
    77→            created_timestamp: get_time_ms(),
    78→        }
    79→    }
    80→
    81→    pub fn is_active(&self) -> bool {
    82→        match self.state {
    83→            ChannelState::Active => true,
    84→            _ => false,
    85→        }
    86→    }
    87→
    88→    pub fn is_ready_for_handshake(&self) -> bool {
    89→        match self.state {
    90→            ChannelState::Idle => true,
    91→            _ => false,
    92→        }
    93→    }
    94→
    95→    pub fn get_channel_duration_ms(&self) -> u64 {
    96→        get_time_ms() - self.created_timestamp
    97→    }
    98→}
    99→
   100→// ============================================================================
   101→// 3. Handshake (키 교환)
   102→// ============================================================================
   103→
   104→pub struct HandshakeMessage {
   105→    pub channel_id: u64,
   106→    pub public_key: [u8; 32],
   107→    pub nonce: [u8; 16],
   108→    pub timestamp: u64,
   109→}
   110→
   111→impl HandshakeMessage {
   112→    pub fn new(channel_id: u64, public_key: &[u8; 32], nonce: &[u8; 16]) -> Self {
   113→        HandshakeMessage {
   114→            channel_id,
   115→            public_key: *public_key,
   116→            nonce: *nonce,
   117→            timestamp: get_time_ms(),
   118→        }
   119→    }
   120→}
   121→
   122→pub fn initiate_handshake(channel: &mut SignalChannel) -> HandshakeMessage {
   123→    // Handshake 시작: 로컬 공개 키를 원격에 전송
   124→    channel.state = ChannelState::Handshake;
   125→
   126→    let nonce = [99u8; 16];  // 간단한 nonce (실제는 랜덤)
   127→
   128→    HandshakeMessage::new(channel.channel_id, &channel.local_key, &nonce)
   129→}
   130→
   131→pub fn complete_handshake(
   132→    channel: &mut SignalChannel,
   133→    remote_key: &[u8; 32],
   134→    remote_nonce: &[u8; 16]
   135→) -> bool {
   136→    // Handshake 완료: 원격 공개 키를 받고 세션 키 생성
   137→    if !channel.is_ready_for_handshake() && !matches!(channel.state, ChannelState::Handshake) {
   138→        return false;
   139→    }
   140→
   141→    channel.remote_key = *remote_key;
   142→
   143→    // ECDH 세션 키 유도 (시뮬레이션)
   144→    let mut session_key_input = Vec::new();
   145→
   146→    for &byte in &channel.local_key {
   147→        session_key_input.push(byte);
   148→    }
   149→    for &byte in remote_key {
   150→        session_key_input.push(byte);
   151→    }
   152→    for &byte in remote_nonce {
   153→        session_key_input.push(byte);
   154→    }
   155→
   156→    // 세션 키 = H(local_key || remote_key || remote_nonce)
   157→    channel.session_key = kdf_derive(&session_key_input[..]);
   158→
   159→    channel.state = ChannelState::Active;
   160→    true
   161→}
   162→
   163→pub fn handshake_complete(channel: &mut SignalChannel, remote_msg: &HandshakeMessage) -> bool {
   164→    complete_handshake(channel, &remote_msg.public_key, &remote_msg.nonce)
   165→}
   166→
   167→// ============================================================================
   168→// 4. 메시지 송수신
   169→// ============================================================================
   170→
   171→pub struct SignalMessage {
   172→    pub channel_id: u64,
   173→    pub sequence: u64,
   174→    pub payload: Vec<u8>,
   175→    pub timestamp: u64,
   176→}
   177→
   178→impl SignalMessage {
   179→    pub fn new(channel_id: u64, sequence: u64, payload: &[u8]) -> Self {
   180→        SignalMessage {
   181→            channel_id,
   182→            sequence,
   183→            payload: payload.to_vec(),
   184→            timestamp: get_time_ms(),
   185→        }
   186→    }
   187→}
   188→
   189→pub fn send_message(channel: &mut SignalChannel, payload: &[u8]) -> Option<SignalMessage> {
   190→    // 활성 채널에서만 메시지 송수신 가능
   191→    if !channel.is_active() {
   192→        return None;
   193→    }
   194→
   195→    channel.message_count += 1;
   196→    channel.bytes_sent += payload.len() as u64;
   197→
   198→    Some(SignalMessage::new(
   199→        channel.channel_id,
   200→        channel.message_count,
   201→        payload
   202→    ))
   203→}
   204→
   205→pub fn receive_message(channel: &mut SignalChannel, msg: &SignalMessage) -> Option<Vec<u8>> {
   206→    // 채널 검증
   207→    if msg.channel_id != channel.channel_id {
   208→        return None;
   209→    }
   210→
   211→    if !channel.is_active() {
   212→        return None;
   213→    }
   214→
   215→    channel.bytes_received += msg.payload.len() as u64;
   216→
   217→    // 메시지 반환
   218→    Some(msg.payload.clone())
   219→}
   220→
   221→// ============================================================================
   222→// 5. 처리량 계산
   223→// ============================================================================
   224→
   225→pub fn throughput_mps(channel: &SignalChannel) -> u32 {
   226→    // 초당 메시지 수 (messages per second)
   227→    let duration_ms = channel.get_channel_duration_ms();
   228→
   229→    if duration_ms == 0 {
   230→        return 0;
   231→    }
   232→
   233→    let mps = (channel.message_count as u64 * 1000) / duration_ms;
   234→    mps as u32
   235→}
   236→
   237→pub fn throughput_mbps(channel: &SignalChannel) -> f32 {
   238→    // 초당 메가비트 수 (megabits per second)
   239→    let duration_ms = channel.get_channel_duration_ms();
   240→
   241→    if duration_ms == 0 {
   242→        return 0.0;
   243→    }
   244→
   245→    let bytes = channel.bytes_sent + channel.bytes_received;
   246→    let bits = bytes as f32 * 8.0;
   247→    let seconds = duration_ms as f32 / 1000.0;
   248→
   249→    (bits / 1_000_000.0) / seconds
   250→}
   251→
