   253→// 6. 채널 통계
   254→// ============================================================================
   255→
   256→pub struct ChannelStats {
   257→    pub channel_id: u64,
   258→    pub message_count: u64,
   259→    pub bytes_sent: u64,
   260→    pub bytes_received: u64,
   261→    pub throughput_mps: u32,
   262→    pub throughput_mbps: f32,
   263→    pub duration_ms: u64,
   264→    pub state: String,
   265→}
