   267→impl ChannelStats {
   268→    pub fn from_channel(channel: &SignalChannel) -> Self {
   269→        let state_str = match &channel.state {
   270→            ChannelState::Idle => "Idle".to_string(),
   271→            ChannelState::Handshake => "Handshake".to_string(),
   272→            ChannelState::Active => "Active".to_string(),
   273→            ChannelState::Closed => "Closed".to_string(),
   274→        };
   275→
   276→        ChannelStats {
   277→            channel_id: channel.channel_id,
   278→            message_count: channel.message_count,
   279→            bytes_sent: channel.bytes_sent,
   280→            bytes_received: channel.bytes_received,
   281→            throughput_mps: throughput_mps(channel),
   282→            throughput_mbps: throughput_mbps(channel),
   283→            duration_ms: channel.get_channel_duration_ms(),
   284→            state: state_str,
   285→        }
   286→    }
   287→}
   288→
   289→// ============================================================================
   290→// 7. 유틸리티 함수
   291→// ============================================================================
   292→
   293→fn kdf_derive(input: &[u8]) -> [u8; 32] {
   294→    // 간단한 KDF (시뮬레이션)
   295→    let mut result = [0u8; 32];
   296→
   297→    let len = input.len().min(32);
   298→    for i in 0..len {
   299→        result[i] = input[i].wrapping_add((i as u8).wrapping_mul(11));
   300→    }
   301→
   302→    // 길이를 해시에 추가
   303→    for i in 24..32 {
   304→        result[i] ^= ((input.len() >> ((i - 24) * 8)) & 0xFF) as u8;
   305→    }
   306→
   307→    result
   308→}
   309→
   310→fn get_time_ms() -> u64 {
   311→    // 시뮬레이션: 간단한 타이머
   312→    static mut COUNTER: u64 = 0;
   313→    unsafe {
   314→        COUNTER += 1;
   315→        COUNTER / 100  // 대략적인 ms 단위
   316→    }
   317→}
