    15→
    16→// ============================================================================
    17→// 1. Signal Event (RingBufferEvent 패턴 특화)
    18→// ============================================================================
    19→
    20→pub struct SignalEvent {
    21→    pub channel_id: u64,
    22→    pub sequence: u64,
    23→    pub payload: [u8; 512],          // 최대 512바이트 페이로드
    24→    pub payload_len: u16,
    25→    pub timestamp_ns: u64,
    26→    pub zkp_proof_hash: [u8; 32],    // ZKP proof 해시
    27→}
    28→
    29→impl SignalEvent {
    30→    pub fn new(
    31→        channel_id: u64,
    32→        sequence: u64,
    33→        payload: &[u8],
    34→        zkp_hash: &[u8; 32]
    35→    ) -> Self {
    36→        let mut event = SignalEvent {
    37→            channel_id,
    38→            sequence,
    39→            payload: [0u8; 512],
    40→            payload_len: 0,
    41→            timestamp_ns: get_time_ns(),
    42→            zkp_proof_hash: *zkp_hash,
    43→        };
    44→
    45→        let len = payload.len().min(512);
    46→        event.payload[0..len].copy_from_slice(&payload[0..len]);
    47→        event.payload_len = len as u16;
    48→
    49→        event
    50→    }
    51→
    52→    pub fn is_valid(&self) -> bool {
    53→        (self.payload_len as usize) <= 512
    54→    }
    55→}
    56→
    57→impl Clone for SignalEvent {
    58→    fn clone(&self) -> Self {
    59→        SignalEvent {
    60→            channel_id: self.channel_id,
    61→            sequence: self.sequence,
    62→            payload: self.payload,
    63→            payload_len: self.payload_len,
