    70→// ============================================================================
    71→// 2. Zero-Copy Ring Buffer (Phase 8 패턴 재사용)
    72→// ============================================================================
    73→
    74→pub struct ZeroCopyRingBuffer {
    75→    pub buffer: Vec<Option<SignalEvent>>,
    76→    pub write_idx: u32,
    77→    pub read_idx: u32,
    78→    pub capacity: u32,
    79→    pub count: u32,
    80→    pub dropped_events: u64,
    81→}
    82→
    83→impl ZeroCopyRingBuffer {
    84→    pub fn new(capacity: u32) -> Self {
    85→        let mut buffer = Vec::new();
    86→
    87→        for _ in 0..capacity {
    88→            buffer.push(None);
    89→        }
    90→
    91→        ZeroCopyRingBuffer {
    92→            buffer,
    93→            write_idx: 0,
    94→            read_idx: 0,
    95→            capacity,
    96→            count: 0,
    97→            dropped_events: 0,
    98→        }
    99→    }
   100→
   101→    pub fn push_event(&mut self, event: SignalEvent) -> bool {
   102→        // 무복사 이벤트 삽입 (포인터만 이동)
   103→        if !event.is_valid() {
   104→            return false;
   105→        }
   106→
   107→        // 버퍼 가득 찼는지 확인
   108→        if self.count >= self.capacity {
   109→            self.dropped_events += 1;
   110→            return false;
   111→        }
   112→
   113→        let idx = self.write_idx as usize;
   114→        self.buffer[idx] = Some(event);
   115→
   116→        self.write_idx = (self.write_idx + 1) % self.capacity;
   117→        self.count += 1;
   118→
   119→        true
   120→    }
   121→
   122→    pub fn pop_event(&mut self) -> Option<SignalEvent> {
   123→        // 무복사 이벤트 추출 (포인터만 이동)
   124→        if self.count == 0 {
   125→            return None;
   126→        }
   127→
   128→        let idx = self.read_idx as usize;
   129→
   130→        if let Some(event) = self.buffer[idx].take() {
   131→            self.read_idx = (self.read_idx + 1) % self.capacity;
   132→            self.count -= 1;
   133→
   134→            Some(event)
   135→        } else {
   136→            None
   137→        }
   138→    }
   139→
   140→    pub fn is_empty(&self) -> bool {
   141→        self.count == 0
   142→    }
   143→
   144→    pub fn is_full(&self) -> bool {
   145→        self.count >= self.capacity
   146→    }
   147→
   148→    pub fn size(&self) -> u32 {
   149→        self.count
   150→    }
   151→
   152→    pub fn loss_rate(&self) -> f32 {
   153→        // 손실률 계산
   154→        let total = self.count as u64 + self.dropped_events;
   155→
   156→        if total == 0 {
   157→            return 0.0;
   158→        }
   159→
   160→        (self.dropped_events as f32 / total as f32) * 100.0
   161→    }
   162→}
   163→
   164→// ============================================================================
   165→// 3. Signal Bus (ZeroCopyRingBuffer 래퍼)
   166→// ============================================================================
   167→
   168→pub struct SignalBus {
   169→    pub ring: ZeroCopyRingBuffer,
   170→    pub batch_size: u32,
   171→    pub processed_batches: u64,
   172→    pub total_events_processed: u64,
   173→}
   174→
   175→impl SignalBus {
   176→    pub fn new(capacity: u32, batch_size: u32) -> Self {
   177→        SignalBus {
   178→            ring: ZeroCopyRingBuffer::new(capacity),
   179→            batch_size,
   180→            processed_batches: 0,
   181→            total_events_processed: 0,
   182→        }
   183→    }
   184→
   185→    pub fn push_signal(&mut self, event: SignalEvent) -> bool {
   186→        self.ring.push_event(event)
   187→    }
   188→
   189→    pub fn pop_signal(&mut self) -> Option<SignalEvent> {
   190→        if let Some(event) = self.ring.pop_event() {
   191→            self.total_events_processed += 1;
   192→            Some(event)
   193→        } else {
   194→            None
   195→        }
   196→    }
   197→
   198→    pub fn process_batch(&mut self) -> Vec<SignalEvent> {
   199→        // Batch 크기만큼 이벤트 처리
   200→        let mut batch = Vec::new();
   201→
   202→        for _ in 0..self.batch_size {
   203→            if let Some(event) = self.pop_signal() {
   204→                batch.push(event);
   205→            } else {
   206→                break;
   207→            }
   208→        }
   209→
   210→        if !batch.is_empty() {
   211→            self.processed_batches += 1;
   212→        }
   213→
   214→        batch
   215→    }
   216→
   217→    pub fn bus_utilization(&self) -> f32 {
   218→        // 버스 사용률 (%)
   219→        if self.ring.capacity == 0 {
   220→            return 0.0;
   221→        }
   222→
   223→        (self.ring.count as f32 / self.ring.capacity as f32) * 100.0
   224→    }
   225→
   226→    pub fn bus_stats(&self) -> BusStats {
   227→        BusStats {
   228→            capacity: self.ring.capacity,
   229→            current_size: self.ring.count,
   230→            dropped_events: self.ring.dropped_events,
   231→            processed_batches: self.processed_batches,
   232→            total_events_processed: self.total_events_processed,
   233→            utilization: self.bus_utilization(),
   234→            loss_rate: self.ring.loss_rate(),
   235→        }
   236→    }
   237→}
   238→
