   264→    }
   265→}
   266→
   267→// ============================================================================
   268→// 5. 유틸리티 함수
   269→// ============================================================================
   270→
   271→fn get_time_ns() -> u64 {
   272→    // 시뮬레이션: 나노초 타이머
   273→    static mut COUNTER: u64 = 0;
   274→    unsafe {
   275→        COUNTER = COUNTER.wrapping_add(1);
   276→        COUNTER
   277→    }
   278→}
