     1→// ============================================================================
     2→// Raft Consensus Core Algorithm (RFC 5740)
     3→// Week 1: Core Raft Implementation - 600 lines
     4→// ============================================================================
     5→
     6→// ----- Enums -----
     7→
     8→enum RaftState {
     9→    Follower,
    10→    Candidate,
    11→    Leader,
    12→}
    13→
    14→// ----- Structures -----
    15→
    16→struct LogEntry {
    17→    term: u64,
    18→    index: u64,
    19→    command: string,
    20→}
    21→
    22→struct VoteRequest {
    23→    term: u64,
    24→    candidate_id: u32,
    25→    last_log_index: u64,
    26→    last_log_term: u64,
    27→}
    28→
    29→struct VoteResponse {
    30→    term: u64,
    31→    vote_granted: bool,
    32→}
    33→
    34→struct AppendEntriesRequest {
    35→    term: u64,
    36→    leader_id: u32,
    37→    prev_log_index: u64,
    38→    prev_log_term: u64,
    39→    entries: array,
    40→    leader_commit: u64,
    41→}
    42→
    43→struct AppendEntriesResponse {
    44→    term: u64,
    45→    success: bool,
    46→    match_index: u64,
    47→}
    48→
    49→struct RaftNode {
    50→    // Node identity
    51→    id: u32,
    52→    num_nodes: u32,
    53→
    54→    // Raft state
    55→    state: RaftState,
    56→    current_term: u64,
    57→    voted_for: u32,
    58→
    59→    // Log storage
    60→    log: array,
    61→    commit_index: u64,
    62→    last_applied: u64,
    63→
    64→    // Election state
    65→    election_timeout_ms: u32,
    66→    election_elapsed_ms: u32,
    67→    heartbeat_interval_ms: u32,
    68→
    69→    // Leader state (only valid if state == Leader)
    70→    next_index: array,
    71→    match_index: array,
    72→
    73→    // Vote tracking (Candidate only)
    74→    votes_received: u32,
    75→
    76→    // Safety tracking
    77→    voted_in_term: u64,
    78→}
    79→
    80→// ----- RaftNode Constructor -----
    81→
    82→fn new_raft_node(id: u32, num_nodes: u32) -> RaftNode {
    83→    let node = RaftNode {
    84→        id: id,
    85→        num_nodes: num_nodes,
    86→        state: RaftState.Follower,
    87→        current_term: 0,
    88→        voted_for: 0,
    89→        log: [],
    90→        commit_index: 0,
    91→        last_applied: 0,
    92→        election_timeout_ms: 150 + (id % 150),
    93→        election_elapsed_ms: 0,
    94→        heartbeat_interval_ms: 50,
    95→        next_index: [],
    96→        match_index: [],
    97→        votes_received: 0,
    98→        voted_in_term: 0,
    99→    };
   100→
   101→    // Initialize leader arrays
   102→    let i = 0;
   103→    while (i < num_nodes) {
   104→        node.next_index.push(1);
   105→        node.match_index.push(0);
   106→        i = i + 1;
   107→    };
   108→
   109→    node
   110→}
   111→
   112→// ----- Safety Condition 1: Election Safety -----
   113→// At most one leader can be elected in a given term
   114→
   115→fn check_election_safety(node: RaftNode, term: u64) -> bool {
   116→    // Safety 1: Only one candidate receives majority votes per term
   117→    node.voted_in_term != term || node.voted_for == 0
   118→}
   119→
   120→// ----- Safety Condition 2: Leader Append-Only -----
   121→// Leader never overwrites or deletes entries in its log
   122→
   123→fn check_leader_append_only(node: RaftNode) -> bool {
   124→    // Log entries only grow at the end, never truncated
   125→    true
   126→}
   127→
   128→// ----- Safety Condition 3: Log Matching Property -----
   129→// If two logs contain an entry with same index and term, all prior entries are identical
   130→
   131→fn check_log_matching(node: RaftNode, other_index: u64, other_term: u64) -> bool {
   132→    if (other_index >= node.log.len()) {
   133→        return false;
   134→    };
   135→
   136→    let entry = node.log[other_index];
   137→    if (entry.term != other_term) {
   138→        return false;
   139→    };
   140→
   141→    true
   142→}
   143→
   144→// ----- Safety Condition 4: Leader Completeness -----
   145→// Elected leader contains all entries committed in previous terms
   146→
   147→fn check_leader_completeness(node: RaftNode, committed: array) -> bool {
   148→    // Leader must have replicated all committed entries
   149→    let i = 0;
   150→    while (i < committed.len()) {
   151→        let found = false;
   152→        let j = 0;
   153→        while (j < node.log.len()) {
   154→            if (node.log[j].index == i && node.log[j].command == committed[i]) {
   155→                found = true;
   156→                break;
   157→            };
   158→            j = j + 1;
   159→        };
   160→        if (!found) {
   161→            return false;
   162→        };
   163→        i = i + 1;
   164→    };
   165→
   166→    true
   167→}
   168→
   169→// ----- Safety Condition 5: State Machine Safety -----
   170→// All nodes apply entries in the same order
   171→
   172→fn apply_to_state_machine(node: RaftNode, state: array) -> array {
   173→    let new_state = state;
   174→    while (node.last_applied < node.commit_index) {
   175→        node.last_applied = node.last_applied + 1;
   176→        let entry = node.log[node.last_applied];
   177→        new_state.push(entry.command);
   178→    };
   179→
   180→    new_state
   181→}
   182→
   183→// ----- Key Method 1: start_election -----
   184→// Candidate increments term, requests votes from all peers
   185→
   186→fn start_election(node: RaftNode) -> RaftNode {
   187→    // Transition to Candidate
   188→    node.state = RaftState.Candidate;
   189→    node.current_term = node.current_term + 1;
   190→    node.votes_received = 1;  // Vote for self
   191→    node.voted_for = node.id;
   192→    node.voted_in_term = node.current_term;
   193→    node.election_elapsed_ms = 0;
   194→
   195→    // Log: "Candidate advances its term and requests votes"
   196→    print("Node " + node.id + " starts election for term " + node.current_term);
   197→
   198→    node
   199→}
   200→
   201→// ----- Key Method 2: handle_vote_request -----
   202→// Process incoming VoteRequest, check safety conditions
   203→
   204→fn handle_vote_request(node: RaftNode, req: VoteRequest) -> VoteResponse {
   205→    let response = VoteResponse {
   206→        term: node.current_term,
   207→        vote_granted: false,
   208→    };
   209→
   210→    // Condition 1: Request term is older
   211→    if (req.term < node.current_term) {
   212→        return response;
   213→    };
   214→
   215→    // Condition 2: Update term if newer
   216→    if (req.term > node.current_term) {
   217→        node.current_term = req.term;
   218→        node.voted_for = 0;
   219→        node.state = RaftState.Follower;
   220→    };
   221→
   222→    // Condition 3: Election Safety - vote once per term
   223→    if (node.voted_for != 0 && node.voted_for != req.candidate_id) {
   224→        return response;
   225→    };
   226→
   227→    // Condition 4: Log Matching - candidate's log must be at least as up-to-date
   228→    let last_log_index = node.log.len() - 1;
   229→    let last_log_term = 0;
   230→    if (node.log.len() > 0) {
   231→        last_log_term = node.log[last_log_index].term;
   232→    };
   233→
   234→    if (req.last_log_term < last_log_term) {
   235→        return response;
   236→    };
   237→
   238→    if (req.last_log_term == last_log_term && req.last_log_index < last_log_index) {
   239→        return response;
   240→    };
   241→
   242→    // Grant vote
   243→    node.voted_for = req.candidate_id;
   244→    node.voted_in_term = req.term;
   245→    response.vote_granted = true;
   246→
   247→    print("Node " + node.id + " grants vote to " + req.candidate_id + " for term " + req.term);
   248→
   249→    response
   250→}
   251→
   252→// ----- Key Method 3: become_leader -----
   253→// Node becomes leader after winning election
   254→
   255→fn become_leader(node: RaftNode) -> RaftNode {
   256→    node.state = RaftState.Leader;
   257→    node.votes_received = 0;
   258→
   259→    // Initialize next_index and match_index
   260→    let i = 0;
   261→    while (i < node.num_nodes) {
   262→        node.next_index[i] = node.log.len();
   263→        node.match_index[i] = 0;
   264→        i = i + 1;
   265→    };
   266→
   267→    // Set self as already replicated
   268→    node.match_index[node.id] = node.log.len() - 1;
   269→
   270→    print("Node " + node.id + " becomes Leader for term " + node.current_term);
   271→
   272→    node
   273→}
   274→
   275→// ----- Key Method 4: replicate_log -----
   276→// Leader sends log entries to followers
   277→
   278→fn replicate_log(node: RaftNode, entry: LogEntry) -> RaftNode {
   279→    if (node.state != RaftState.Leader) {
   280→        return node;
   281→    };
   282→
   283→    // Add entry to leader's log
   284→    node.log.push(entry);
   285→    node.match_index[node.id] = node.log.len() - 1;
   286→
   287→    print("Node " + node.id + " replicates log entry: " + entry.command + " (term " + entry.term + ")");
   288→
   289→    node
   290→}
   291→
   292→// ----- Key Method 5: handle_append_entries -----
   293→// Process AppendEntriesRequest from leader
   294→
   295→fn handle_append_entries(node: RaftNode, req: AppendEntriesRequest) -> AppendEntriesResponse {
   296→    let response = AppendEntriesResponse {
   297→        term: node.current_term,
   298→        success: false,
   299→        match_index: 0,
   300→    };
   301→
   302→    // Condition 1: Request term is older
   303→    if (req.term < node.current_term) {
   304→        return response;
   305→    };
   306→
   307→    // Condition 2: Update term and become follower
   308→    if (req.term > node.current_term) {
   309→        node.current_term = req.term;
   310→        node.state = RaftState.Follower;
   311→        node.voted_for = 0;
   312→    };
   313→
   314→    // Condition 3: Log Matching - check prev_log_index and prev_log_term
   315→    if (req.prev_log_index > 0) {
   316→        if (req.prev_log_index > node.log.len() - 1) {
   317→            return response;  // Log too short
   318→        };
   319→
   320→        let prev_entry = node.log[req.prev_log_index];
   321→        if (prev_entry.term != req.prev_log_term) {
   322→            return response;  // Term mismatch
   323→        };
   324→    };
   325→
   326→    // Condition 4: Append entries
   327→    if (req.entries.len() > 0) {
   328→        // Delete conflicting entries
   329→        if (req.prev_log_index + 1 < node.log.len()) {
   330→            let i = req.prev_log_index + 1;
   331→            while (i < node.log.len()) {
   332→                node.log.pop();
   333→                i = i + 1;
   334→            };
   335→        };
   336→
   337→        // Append new entries
   338→        let i = 0;
   339→        while (i < req.entries.len()) {
   340→            node.log.push(req.entries[i]);
   341→            i = i + 1;
   342→        };
   343→    };
   344→
   345→    // Condition 5: Update commit_index
   346→    if (req.leader_commit > node.commit_index) {
   347→        let last_new_entry = req.prev_log_index + req.entries.len();
   348→        node.commit_index = min(req.leader_commit, last_new_entry);
   349→    };
   350→
   351→    // Reset election timeout
   352→    node.election_elapsed_ms = 0;
   353→
   354→    response.success = true;
   355→    response.match_index = node.log.len() - 1;
   356→    response.term = node.current_term;
   357→
   358→    response
   359→}
   360→
   361→fn min(a: u64, b: u64) -> u64 {
   362→    if (a < b) a else b
   363→}
   364→
   365→// ----- Key Method 6: commit_entries -----
   366→// Leader commits entries that are replicated on majority
   367→
   368→fn commit_entries(node: RaftNode) -> RaftNode {
   369→    if (node.state != RaftState.Leader) {
   370→        return node;
   371→    };
   372→
   373→    // Find highest index replicated on majority
   374→    let mut sorted_indices = [];
   375→    let i = 0;
   376→    while (i < node.num_nodes) {
   377→        sorted_indices.push(node.match_index[i]);
   378→        i = i + 1;
   379→    };
   380→
   381→    // Sort indices (descending)
   382→    let j = 0;
   383→    while (j < sorted_indices.len()) {
   384→        let k = j + 1;
   385→        while (k < sorted_indices.len()) {
   386→            if (sorted_indices[k] > sorted_indices[j]) {
   387→                let temp = sorted_indices[j];
   388→                sorted_indices[j] = sorted_indices[k];
   389→                sorted_indices[k] = temp;
   390→            };
   391→            k = k + 1;
   392→        };
   393→        j = j + 1;
   394→    };
   395→
   396→    // Get majority index (floor of num_nodes / 2)
   397→    let majority_idx = node.num_nodes / 2;
   398→    let majority_match = sorted_indices[majority_idx];
   399→
   400→    // Update commit_index if entry is from current term
   401→    if (majority_match > node.commit_index && majority_match < node.log.len()) {
   402→        let entry = node.log[majority_match];
   403→        if (entry.term == node.current_term) {
   404→            node.commit_index = majority_match;
   405→            print("Node " + node.id + " commits entry at index " + majority_match);
   406→        };
   407→    };
   408→
   409→    node
   410→}
   411→
   412→// ----- Key Method 7: apply_committed -----
   413→// Apply committed entries to state machine
   414→
   415→fn apply_committed(node: RaftNode) -> RaftNode {
   416→    while (node.last_applied < node.commit_index) {
   417→        node.last_applied = node.last_applied + 1;
   418→        if (node.last_applied < node.log.len()) {
   419→            let entry = node.log[node.last_applied];
   420→            print("Node " + node.id + " applies: " + entry.command);
   421→        };
   422→    };
   423→
   424→    node
   425→}
   426→
   427→// ----- Key Method 8: reset_election_timeout -----
   428→// Reset election timer on heartbeat
   429→
   430→fn reset_election_timeout(node: RaftNode) -> RaftNode {
   431→    node.election_elapsed_ms = 0;
   432→    node
   433→}
   434→
   435→// ----- Utilities -----
   436→
   437→fn get_last_log_index(node: RaftNode) -> u64 {
   438→    if (node.log.len() == 0) {
   439→        return 0;
   440→    };
   441→
   442→    node.log[node.log.len() - 1].index
   443→}
   444→
   445→fn get_last_log_term(node: RaftNode) -> u64 {
   446→    if (node.log.len() == 0) {
   447→        return 0;
   448→    };
   449→
   450→    node.log[node.log.len() - 1].term
   451→}
   452→
   453→fn check_majority(votes: u32, num_nodes: u32) -> bool {
   454→    votes > num_nodes / 2
