   285→// ----- Balancing Statistics -----
   286→
   287→struct BalanceStats {
   288→    node_id: u32,
   289→    key_count: u32,
   290→    total_size: u64,
   291→}
   292→
   293→fn get_balance_stats(store: ShardedKVStore) -> array {
   294→    let stats = [];
   295→
   296→    // Count keys per node
   297→    let node_counts = {};
   298→
   299→    // For each key, find its primary node
   300→    for key in store.data {
   301→        let primary = get_node_for_key(store.ring, key);
   302→
   303→        if (!node_counts[primary]) {
   304→            node_counts[primary] = 0;
   305→        };
   306→
   307→        node_counts[primary] = node_counts[primary] + 1;
   308→    };
   309→
   310→    // Convert to array
   311→    for node_id in store.ring.node_list {
   312→        let count = node_counts[node_id] || 0;
   313→
   314→        let stat = BalanceStats {
   315→            node_id: node_id,
   316→            key_count: count,
   317→            total_size: count * 100,  // Assume 100 bytes per key
   318→        };
   319→
   320→        stats.push(stat);
   321→    };
   322→
   323→    stats
   324→}
   325→
   326→fn check_balance(store: ShardedKVStore) -> bool {
   327→    let stats = get_balance_stats(store);
   328→
   329→    if (stats.len() < 2) {
   330→        return true;
   331→    };
   332→
   333→    // Check if keys are roughly balanced
   334→    let total_keys = 0;
   335→    let i = 0;
   336→    while (i < stats.len()) {
   337→        total_keys = total_keys + stats[i].key_count;
   338→        i = i + 1;
   339→    };
   340→
   341→    let avg_keys = total_keys / stats.len();
   342→    let threshold = avg_keys / 2;  // Allow ±50%
   343→
   344→    // Check each node
   345→    let balanced = true;
   346→    let j = 0;
   347→    while (j < stats.len()) {
   348→        let deviation = abs(stats[j].key_count as i64 - avg_keys as i64);
   349→        if (deviation > threshold as i64) {
   350→            balanced = false;
   351→            break;
   352→        };
   353→        j = j + 1;
   354→    };
   355→
   356→    balanced
   357→}
   358→
   359→fn abs(x: i64) -> i64 {
   360→    if (x < 0) -x else x
   361→}
   362→
   363→// ----- Hotspot Detection -----
   364→
   365→fn detect_hotspots(store: ShardedKVStore) -> array {
   366→    let stats = get_balance_stats(store);
   367→    let hotspots = [];
   368→
   369→    // Calculate average and std dev
   370→    let total = 0;
   371→    let i = 0;
   372→    while (i < stats.len()) {
   373→        total = total + stats[i].key_count;
   374→        i = i + 1;
   375→    };
   376→
   377→    let avg = total / stats.len();
   378→    let sum_sq_diff = 0;
   379→    let j = 0;
   380→    while (j < stats.len()) {
   381→        let diff = stats[j].key_count as i64 - avg as i64;
   382→        sum_sq_diff = sum_sq_diff + (diff * diff) as u64;
   383→        j = j + 1;
   384→    };
   385→
   386→    let variance = sum_sq_diff / stats.len();
   387→    let std_dev = sqrt(variance);
   388→
   389→    // Find hotspots (>2 std dev from mean)
   390→    let k = 0;
   391→    while (k < stats.len()) {
   392→        if (stats[k].key_count > avg + 2 * std_dev) {
   393→            hotspots.push(stats[k].node_id);
   394→        };
   395→        k = k + 1;
   396→    };
   397→
   398→    hotspots
   399→}
   400→
   401→fn sqrt(x: u64) -> u64 {
   402→    // Simple sqrt approximation
   403→    if (x == 0) return 0;
   404→
   405→    let result = x;
   406→    let i = 0;
   407→    while (i < 10) {
   408→        result = (result + x / result) / 2;
   409→        i = i + 1;
   410→    };
   411→
   412→    result
   413→}
