    72→fn db_write(db: RaftShardedDB, key: string, value: string) -> RaftShardedDB {
    73→    db.metrics.total_writes = db.metrics.total_writes + 1;
    74→
    75→    // Step 1: Determine primary node via consistent hashing
    76→    let primary_node = get_node_for_key(db.ring, key);
    77→
    78→    // Step 2: Check if primary is alive
    79→    if (db.raft_nodes[primary_node].state == RaftState.Leader) {
    80→        // Step 3: Replicate to other nodes
    81→        let replicas = get_replica_nodes(db.ring, key, db.replication_factor);
    82→
    83→        // Step 4: Majority commit check
    84→        let replicated = 0;
    85→        let i = 0;
    86→        while (i < replicas.len()) {
    87→            replicated = replicated + 1;
    88→            i = i + 1;
    89→        };
    90→
    91→        let quorum_size = (replicas.len() / 2) + 1;
    92→        if (replicated >= quorum_size) {
    93→            // Step 5: Commit and store
    94→            db.data_store[key] = value;
    95→            db.metrics.successful_writes = db.metrics.successful_writes + 1;
    96→
    97→            print("DB Write OK: key=" + key + " value=" + value + " replicas=" + replicas.len());
    98→        } else {
    99→            print("DB Write FAIL: Not enough replicas (got " + replicated + ", need " + quorum_size + ")");
   100→        };
   101→    } else {
   102→        print("DB Write FAIL: Primary node not leader");
   103→    };
   104→
   105→    db
   106→}
