   108→// ----- Read Operation -----
   109→
   110→fn db_read(db: RaftShardedDB, key: string) -> string {
   111→    db.metrics.total_reads = db.metrics.total_reads + 1;
   112→
   113→    // Try primary first
   114→    let primary_node = get_node_for_key(db.ring, key);
   115→
   116→    if (db.raft_nodes[primary_node].state == RaftState.Leader ||
   117→        db.raft_nodes[primary_node].state == RaftState.Follower) {
   118→        let value = db.data_store[key];
   119→        if (value.len() > 0) {
   120→            db.metrics.successful_reads = db.metrics.successful_reads + 1;
   121→            print("DB Read OK: key=" + key + " value=" + value);
   122→            return value;
   123→        };
   124→    };
   125→
   126→    // Try replicas
   127→    let replicas = get_replica_nodes(db.ring, key, db.replication_factor);
   128→    let i = 0;
   129→    while (i < replicas.len()) {
   130→        let replica_id = replicas[i];
   131→        if (db.raft_nodes[replica_id].state != RaftState.Leader) {
   132→            // Try stale read from replica
   133→            let value = db.data_store[key];
   134→            if (value.len() > 0) {
   135→                db.metrics.successful_reads = db.metrics.successful_reads + 1;
   136→                print("DB Read OK (from replica): key=" + key);
   137→                return value;
   138→            };
   139→        };
   140→        i = i + 1;
   141→    };
   142→
   143→    print("DB Read FAIL: Key not found");
   144→    ""
   145→}
