     1→/* ============================================================================
     2→   ARM64 Memory Initialization & MMU Configuration
     3→
     4→   목적: ARM64 MMU, 페이지 테이블, 메모리 레이아웃 초기화
     5→   크기: ~300줄
     6→   성능: MMU < 10ms, 페이지 매핑 < 5µs
     7→============================================================================ */
     8→
     9→use crate::boot::arm64_entry::*;
    10→
    11→// ============================================================================
    12→// 1. ARM64 페이지 테이블 엔트리 (PTE)
    13→// ============================================================================
    14→
    15→pub struct Arm64PageTableEntry {
    16→    pub valid: bool,               // [0]: 유효성 플래그
    17→    pub table_or_page: bool,       // [1]: 0=Block/Page, 1=Table
    18→    pub phys_addr: u64,            // [47:12]: 물리 주소
    19→    pub af: bool,                  // [10]: Access Flag
    20→    pub sh: u8,                    // [9:8]: Shareability (0=Non, 2=Outer, 3=Inner)
    21→    pub ap: u8,                    // [7:6]: Access Permission (0=RW, 1=RO, 2=User-RW, 3=User-RO)
    22→    pub ns: bool,                  // [5]: Non-Secure
    23→    pub xn: bool,                  // [54]: Execute Never
    24→}
    25→
    26→impl Arm64PageTableEntry {
    27→    pub fn new() -> Self {
    28→        Arm64PageTableEntry {
    29→            valid: false,
    30→            table_or_page: false,
    31→            phys_addr: 0,
    32→            af: false,
    33→            sh: 0,
    34→            ap: 0,
    35→            ns: false,
    36→            xn: false,
    37→        }
    38→    }
    39→
    40→    // PTE를 u64 형식으로 인코딩
    41→    pub fn encode(&self) -> u64 {
    42→        let mut entry = 0u64;
    43→
    44→        if self.valid {
    45→            entry |= 1 << 0;
    46→        }
    47→
    48→        if self.table_or_page {
    49→            entry |= 1 << 1;
    50→        }
    51→
    52→        // 물리 주소 [47:12]
    53→        entry |= (self.phys_addr & 0x0000_FFFF_FFFF_F000) << 0;
    54→
    55→        if self.af {
    56→            entry |= 1 << 10;
    57→        }
    58→
    59→        entry |= ((self.sh as u64) & 0x3) << 8;
    60→        entry |= ((self.ap as u64) & 0x3) << 6;
    61→
    62→        if self.ns {
    63→            entry |= 1 << 5;
    64→        }
    65→
    66→        if self.xn {
    67→            entry |= 1 << 54;
    68→        }
    69→
    70→        entry
    71→    }
    72→
    73→    // u64에서 PTE 디코딩
    74→    pub fn decode(entry: u64) -> Self {
    75→        Arm64PageTableEntry {
    76→            valid: (entry & 1) != 0,
    77→            table_or_page: ((entry >> 1) & 1) != 0,
    78→            phys_addr: (entry & 0x0000_FFFF_FFFF_F000) as u64,
    79→            af: ((entry >> 10) & 1) != 0,
    80→            sh: ((entry >> 8) & 0x3) as u8,
    81→            ap: ((entry >> 6) & 0x3) as u8,
    82→            ns: ((entry >> 5) & 1) != 0,
    83→            xn: ((entry >> 54) & 1) != 0,
    84→        }
    85→    }
    86→}
    87→
    88→// ============================================================================
    89→// 2. ARM64 페이지 테이블 구조 (4-level: L0~L3)
    90→// ============================================================================
    91→
    92→pub struct Arm64PageTable {
    93→    pub level: u32,                // 0=L0, 1=L1, 2=L2, 3=L3
    94→    pub entries: [u64; 512],       // 512 엔트리 (각 8 bytes = 4KB 페이지)
    95→    pub entry_count: u32,
    96→}
    97→
    98→impl Arm64PageTable {
    99→    pub fn new(level: u32) -> Self {
   100→        Arm64PageTable {
   101→            level: level,
   102→            entries: [0u64; 512],
   103→            entry_count: 0,
   104→        }
   105→    }
   106→
   107→    // 엔트리 설정
   108→    pub fn set_entry(&mut self, index: u32, entry: u64) -> bool {
   109→        if index >= 512 {
   110→            return false;
   111→        }
   112→        self.entries[index as usize] = entry;
   113→        self.entry_count += 1;
   114→        true
   115→    }
   116→
   117→    // 엔트리 조회
   118→    pub fn get_entry(&self, index: u32) -> Option<u64> {
   119→        if index >= 512 {
   120→            None
   121→        } else {
   122→            Some(self.entries[index as usize])
   123→        }
   124→    }
   125→
   126→    // 페이지 테이블 크기 (4KB)
   127→    pub fn size_bytes() -> u32 {
   128→        4096
   129→    }
   130→}
   131→
   132→// ============================================================================
   133→// 3. ARM64 MMU 상태
   134→// ============================================================================
   135→
   136→pub struct Arm64Mmu {
   137→    pub ttbr0_el1: u64,            // Translation Table Base Register 0 (User VA)
   138→    pub ttbr1_el1: u64,            // Translation Table Base Register 1 (Kernel VA)
   139→    pub tcr_el1: u64,              // Translation Control Register
   140→    pub sctlr_el1: u64,            // System Control Register (MMU enable bit)
   141→    pub mair_el1: u64,             // Memory Attribute Indirection Register
   142→    pub page_tables: Vec<Arm64PageTable>,
   143→    pub enabled: bool,
   144→}
   145→
   146→impl Arm64Mmu {
   147→    pub fn new() -> Self {
   148→        Arm64Mmu {
   149→            ttbr0_el1: 0,
   150→            ttbr1_el1: 0,
   151→            tcr_el1: 0,
   152→            sctlr_el1: 0,
   153→            mair_el1: 0,
   154→            page_tables: Vec::new(),
   155→            enabled: false,
   156→        }
   157→    }
   158→
   159→    // MMU 활성화
   160→    pub fn enable(&mut self) {
   161→        self.sctlr_el1 |= 1 << 0;  // M bit: MMU enable
   162→        self.enabled = true;
   163→    }
   164→
   165→    // MMU 비활성화
   166→    pub fn disable(&mut self) {
   167→        self.sctlr_el1 &= !(1 << 0);  // M bit clear
   168→        self.enabled = false;
   169→    }
   170→
   171→    // TLB 플러시
   172→    pub fn flush_tlb(&mut self) {
   173→        // 시뮬레이션: TLBI VMALLE1IS (모든 VA 무효화)
   174→    }
   175→}
   176→
   177→// ============================================================================
   178→// 4. Nano-Kernel 메모리 레이아웃
   179→// ============================================================================
   180→
   181→pub struct NanoKernelMemoryLayout {
   182→    pub kernel_start: u64,          // 0xFFFF_0000_0000_0000 (EL1 상위)
   183→    pub kernel_size: u64,           // 1MB
   184→    pub stack_start: u64,           // 0xFFFF_0000_0020_0000 (kernel_start + 2MB)
   185→    pub stack_size: u64,            // 256KB
   186→    pub heap_start: u64,            // 0xFFFF_0000_0030_0000 (stack_start + 256KB)
   187→    pub heap_size: u64,             // 768KB
   188→    pub fb_start: u64,              // 0xFFFF_0000_0100_0000 (framebuffer)
   189→    pub fb_size: u64,               // 8MB
   190→}
   191→
   192→impl NanoKernelMemoryLayout {
   193→    pub fn new() -> Self {
   194→        NanoKernelMemoryLayout {
   195→            kernel_start: 0xFFFF_0000_0000_0000,
   196→            kernel_size: 1048576,  // 1MB
   197→            stack_start: 0xFFFF_0000_0020_0000,
   198→            stack_size: 262144,    // 256KB
   199→            heap_start: 0xFFFF_0000_0030_0000,
   200→            heap_size: 786432,     // 768KB
   201→            fb_start: 0xFFFF_0000_0100_0000,
   202→            fb_size: 8388608,      // 8MB
   203→        }
   204→    }
   205→
   206→    // 주소가 커널 영역 내인지 검증
   207→    pub fn is_kernel_addr(&self, addr: u64) -> bool {
   208→        addr >= self.kernel_start && addr < (self.kernel_start + self.kernel_size)
   209→    }
   210→
   211→    // 주소가 스택 영역 내인지 검증
   212→    pub fn is_stack_addr(&self, addr: u64) -> bool {
   213→        addr >= self.stack_start && addr < (self.stack_start + self.stack_size)
   214→    }
   215→
   216→    // 주소가 힙 영역 내인지 검증
   217→    pub fn is_heap_addr(&self, addr: u64) -> bool {
   218→        addr >= self.heap_start && addr < (self.heap_start + self.heap_size)
   219→    }
   220→
   221→    // 주소가 framebuffer 영역 내인지 검증
   222→    pub fn is_fb_addr(&self, addr: u64) -> bool {
   223→        addr >= self.fb_start && addr < (self.fb_start + self.fb_size)
   224→    }
   225→}
   226→
   227→// ============================================================================
   228→// 5. 메모리 초기화 함수들
   229→// ============================================================================
   230→
   231→// MMU 초기화
   232→pub fn init_mmu() -> (NanoKernelMemoryLayout, Arm64Mmu) {
   233→    let layout = NanoKernelMemoryLayout::new();
   234→    let mut mmu = Arm64Mmu::new();
   235→
   236→    // TCR_EL1 설정 (Translation Control Register)
   237→    // - T0SZ = 16 (2^48 user space)
   238→    // - T1SZ = 16 (2^48 kernel space)
   239→    mmu.tcr_el1 = (16 << 0) | (16 << 16);
   240→
   241→    // MAIR_EL1 설정 (Memory Attribute Indirection Register)
   242→    // - Device memory
   243→    // - Normal memory
   244→    mmu.mair_el1 = 0x00FF;
   245→
   246→    // TTBR1_EL1 설정 (커널 페이지 테이블 베이스)
   247→    mmu.ttbr1_el1 = layout.kernel_start;
   248→
   249→    // SCTLR_EL1 기본 설정
   250→    // - M bit (MMU) = 0 (초기에는 비활성)
   251→    // - C bit (D-cache) = 1
   252→    // - I bit (I-cache) = 1
   253→    // - Z bit (branch prediction) = 1
   254→    mmu.sctlr_el1 = 0x00C50030;
   255→
   256→    (layout, mmu)
   257→}
   258→
   259→// 커널 영역 매핑
   260→pub fn map_kernel_pages(mmu: &mut Arm64Mmu, layout: &NanoKernelMemoryLayout) -> bool {
   261→    // L0 페이지 테이블 생성
   262→    let mut l0_table = Arm64PageTable::new(0);
   263→
   264→    // L0[511]을 L1 테이블로 설정 (커널 공간)
   265→    let l1_entry = 0xFFFF_0000_0000_0000 | 0x3;  // valid + table
   266→    if !l0_table.set_entry(511, l1_entry) {
   267→        return false;
   268→    }
   269→
   270→    mmu.page_tables.push(l0_table);
   271→
   272→    // L1 페이지 테이블 생성
   273→    let mut l1_table = Arm64PageTable::new(1);
   274→
   275→    // L1[0]을 L2 테이블로 설정 (커널 영역)
   276→    let l2_entry = 0xFFFF_0000_0000_0000 | 0x3;  // valid + table
   277→    if !l1_table.set_entry(0, l2_entry) {
   278→        return false;
   279→    }
   280→
   281→    mmu.page_tables.push(l1_table);
   282→
   283→    // L2 페이지 테이블 생성
   284→    let mut l2_table = Arm64PageTable::new(2);
   285→
   286→    // L2[0~3]: 커널 영역 (2MB 블록)
   287→    for i in 0..4 {
   288→        let phys_addr = (i as u64) * 0x20_0000;
   289→        let pte = Arm64PageTableEntry {
   290→            valid: true,
   291→            table_or_page: false,  // Block
   292→            phys_addr: phys_addr,
   293→            af: true,
   294→            sh: 3,  // Inner shareable
   295→            ap: 0,  // RW
   296→            ns: false,
   297→            xn: false,
   298→        };
   299→        if !l2_table.set_entry(i as u32, pte.encode()) {
   300→            return false;
   301→        }
   302→    }
   303→
   304→    mmu.page_tables.push(l2_table);
   305→
   306→    true
   307→}
   308→
   309→// Framebuffer 매핑
   310→pub fn map_framebuffer(mmu: &mut Arm64Mmu, layout: &NanoKernelMemoryLayout) -> bool {
   311→    // 시뮬레이션: Framebuffer를 커널 공간에 매핑
   312→    // 실제로는 L3 페이지 테이블을 추가하여 4KB 페이지 단위로 매핑
   313→
   314→    if !layout.is_fb_addr(layout.fb_start) {
   315→        return false;
   316→    }
   317→
   318→    // Framebuffer 영역 검증 (< 10MB)
   319→    if layout.fb_size > 10 * 1024 * 1024 {
   320→        return false;
   321→    }
   322→
   323→    true
   324→}
