   326→// ============================================================================
   327→// 6. 검증 함수
   328→// ============================================================================
   329→
   330→// PTE 인코딩/디코딩 일관성 검증
   331→pub fn validate_pte_encoding() -> bool {
   332→    let original = Arm64PageTableEntry {
   333→        valid: true,
   334→        table_or_page: true,
   335→        phys_addr: 0x1000,
   336→        af: true,
   337→        sh: 3,
   338→        ap: 0,
   339→        ns: false,
   340→        xn: false,
   341→    };
   342→
   343→    let encoded = original.encode();
   344→    let decoded = Arm64PageTableEntry::decode(encoded);
   345→
   346→    if decoded.valid != original.valid {
   347→        return false;
   348→    }
   349→    if decoded.phys_addr != original.phys_addr {
   350→        return false;
   351→    }
   352→
   353→    true
   354→}
   355→
   356→// MMU 설정 검증
   357→pub fn validate_mmu_config(mmu: &Arm64Mmu) -> bool {
   358→    // SCTLR_EL1 기본 비트 검증
   359→    if (mmu.sctlr_el1 & 0x1) != 0 {
   360→        // MMU는 초기에 비활성이어야 함
   361→        return false;
   362→    }
   363→
   364→    // TTBR1_EL1 검증 (0이 아니어야 함)
   365→    if mmu.ttbr1_el1 == 0 {
   366→        return false;
   367→    }
   368→
   369→    true
   370→}
   371→
   372→// 메모리 레이아웃 검증
   373→pub fn validate_memory_layout(layout: &NanoKernelMemoryLayout) -> bool {
   374→    // 커널 크기 검증 (< 1MB)
   375→    if layout.kernel_size >= 1048576 {
   376→        return false;
   377→    }
   378→
   379→    // 영역 겹침 검증
   380→    let stack_end = layout.stack_start + layout.stack_size;
   381→    if stack_end > layout.heap_start {
   382→        return false;  // Stack/Heap 겹침
   383→    }
   384→
   385→    let heap_end = layout.heap_start + layout.heap_size;
   386→    if heap_end > layout.fb_start {
   387→        return false;  // Heap/FB 겹침
   388→    }
   389→
   390→    true
   391→}
   392→
   393→// MMU 활성화 검증
   394→pub fn validate_mmu_enable(mmu: &Arm64Mmu) -> bool {
   395→    if !mmu.enabled {
   396→        return false;
   397→    }
   398→
   399→    // M bit 검증
   400→    if (mmu.sctlr_el1 & 1) == 0 {
   401→        return false;
   402→    }
   403→
   404→    true
   405→}
